        if not 0 <= index <= self._len:
            raise IndexError(index)
        if index == 0:
            self.prepend(x)
            return
        cur = self._head
        for _ in range(index - 1):
            cur = cur.next
        cur.next = _Node(x, cur.next)
        self._len += 1

    def remove(self, x):
        prev, cur = None, self._head
        while cur:
            if cur.value == x:
                if prev:
                    prev.next = cur.next
                else:
                    self._head = cur.next
                self._len -= 1
                return
            prev, cur = cur, cur.next
        raise ValueError(x)

