        if self._head is None:
            raise IndexError("empty")
        v = self._head.value
        self._head = self._head.next
        self._len -= 1
        return v

    def reverse(self):
        prev, cur = None, self._head
        while cur:
            cur.next, prev, cur = prev, cur, cur.next
        self._head = prev

