def transpose(m):
    """Transpose a rectangular list-of-lists matrix. [] -> []. Ragged input -> ValueError."""
    if not m:
        return []
    w = len(m[0])
    if any(len(r) != w for r in m):
        raise ValueError("ragged")
    return [[m[i][j] for i in range(len(m))] for j in range(w)]


