def round_half_up(x, digits=0):
    """Round half away from zero (not banker's rounding): 0.5 -> 1, 1.5 -> 2, 2.5 -> 3, -0.5 -> -1."""
    f = 10 ** digits
    y = abs(x) * f
    r = int(y + 0.5)
    return (r if x >= 0 else -r) / f if digits > 0 else (r if x >= 0 else -r)


