assert inv.low_stock() == ["apple"]
inv.receive("fig", 1)
assert inv.low_stock() == ["apple"]
inv2 = Inventory()
inv2.add_item(Item("zed", 1))
inv2.add_item(Item("bee", 1))
assert inv2.low_stock() == ["bee", "zed"]

