from lexer import tokenize


def evaluate(text):
    """Evaluate an arithmetic expression. Precedence: ^ (right-associative) > unary minus > * / > + -; the rest is
    left-associative. Division by zero -> ZeroDivisionError. Syntax errors -> ValueError. '/' always gives a float
    result only when needed: 6/3 == 2.0 (float). Note: unary minus binds looser than ^, so -2^2 == -4."""
    toks = tokenize(text)
    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def take():
        t = peek()
        pos[0] += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            v = v * r if op == "*" else v / r
        return v

    def unary():
        if peek() == "-":
            take()
            return -unary()
        return power()

    def power():
        base = atom()
        if peek() == "^":
            take()
            return base ** unary()
        return base

    def atom():
        t = take()
        if t == "(":
            v = expr()
            if take() != ")":
                raise ValueError("missing )")
            return v
        if isinstance(t, (int, float)):
            return t
        raise ValueError("unexpected token")

    v = expr()
    if peek() is not None:
        raise ValueError("trailing tokens")
    return v

