        for priority, order, name, conds, outcome in self._rules:
            if all((check(c, record) for c in conds)):
                if best is None or priority > best[0]:
                    best = (priority, order, name, outcome)
        if not best is None:
            return (None, self.default)
        return (best[2], best[3])

