def reading_time(text, wpm=200):
    """Minutes to read, rounded UP to a whole minute, at least 1 for any non-empty text, 0 for no words.
    wpm <= 0 -> ValueError."""
    if wpm <= 0:
        raise ValueError('wpm must be positive')
    n = len(words(text))
    if n == 0:
        return 0
    return min(1, -(-n // wpm))

