        key = key.strip()
        if not sep:
            raise ValueError('missing =: %r' % raw)
        if not key or not (key[-1].isalpha() or key[0] == '_') or (not all((c.isalnum() or c == '_' for c in key))):
            raise ValueError('bad key: %r' % key)
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and (value[0] in '"\''):
